import json
from pathlib import Path
import numpy as np
R=Path('decoder_results');r=json.loads((R/'metrics.json').read_text());seeds=list(r['seeds']);assert len(seeds)==3
models=['original_joint','original_aligned'];
if all('recognition' in r['seeds'][s]['models'] for s in seeds):models+=['recognition']
cases=['corrupted','clean','noisy','partial_erasure','missing_frequency'];modes=['generated','oracle0','oracle1','oracle2','oracle_all']
def avg(v):return f'{np.mean(v):.2f} ± {np.std(v,ddof=1):.2f}'
def val(n,c,mode,kind,k):return [r['seeds'][s]['models'][n]['cases'][c][mode][kind][k] for s in seeds]
def pct(v):return avg(np.array(v)*100)
L=['# Frozen decoder/hierarchy sensitivity and recognition-aware experiment','', 'Three seeds, fixed previously used splits. Percentages are mean ± sample SD. Oracle interventions are diagnostics and are not deployable recognition results. Existing models/checkpoints were preserved.','', '## Protocol and interpretation','', '- Frozen CNN, original four-token adapter, 1→2→4 acoustic VQ books, 34,570-parameter NCM architecture. Original-joint and original-aligned checkpoints are loaded unchanged. These codes describe the observed audio, not clean-label digit sequences.', '- An individual oracle replaces exactly one acoustic-code level. All later levels are regenerated conditional on the actual earlier generated/injected codes; unused target levels never enter their queries. The all-oracle case injects all levels. Fixed-suffix controls replace one level but keep every other originally generated code fixed, separating direct decoder effects from downstream changes.', '- Categorical perturbation changes only the first slot of one generated level to (index+1) modulo 64 and keeps other codes fixed. Index proximity has no semantic meaning: this measures one deterministic perturbation, not a code-distance curve or exhaustive sensitivity bound.', '- Per-level latent MSE compares reconstructed prefixes with the observed unquantized adapter input. Code-vector MSE compares lookup embeddings to canonical lookup embeddings. These are acoustic representation metrics, not recognition objectives.', '- Raw digit predictions enumerate all 10,000 four-digit sequences independently. Protected predictions keep the exact previous CNN, frozen gate/acceptance and candidate policies. Scores at accepted positions are replaced by NCM digit probabilities; there is no learned additive fusion weight in the current implementation. Candidate sequence scores multiply digit probabilities. Rejected positions retain CNN scores.', '- Probability interpolation alpha in {0,.25,.5,.75,1} is a diagnostic fusion control. Alpha is selected by digit NLL using only the existing validation fitting half. Test results report that fixed validation-selected alpha. Thus alpha=0 uses CNN scores within the same candidate list, not a new CNN/candidate baseline.', '- Training eligibility is determined before training from the other validation half: oracle L2/L3/all improves raw digit accuracy by at least 0.5 percentage points for either frozen model. This is a weak diagnostic signal, not evidence of deployable improvement. Seeds that qualify receive exactly one fixed recognition-aware variant, with no weight search or test tuning.', '- Recognition-aware loss = 0.1 mean code CE + mean generated-prefix digit CE + 0.25 mean generated-prefix ranking loss. Ranking uses softplus(1+highest incorrect logit−correct logit), only at training positions accepted by the frozen audio-only gate. Target digits supervise losses only. Hard argmax codes are used forward, with straight-through soft-embedding gradients. Earlier levels are generated during both training and inference.', '- Paired training data (1,200 corrupted recordings plus clean seed817), batch128, 16 epochs/1,200 updates, AdamW lr.001 and norm cap1 match the original experiment. Training begins from the same per-seed initialization rather than warm-starting a checkpoint. The new ranking term is the controlled change relative to original-joint. Temperatures use the fixed validation fitting half; oracle diagnostics reuse each model’s ordinary-inference temperature, without oracle-specific calibration.', '- Test: corrupted270, clean270 (seed318), noise68 and partial-erasure67 subsets, row-only missing-frequency270 (seed818). Reused development test combinations limit confirmatory claims. No absent frequency information can be reconstructed by a code oracle.','', '## Validation decision','']
for s in seeds:L.append(f"- Seed {s}: train={r['seeds'][s]['training_trigger']}; {json.dumps(r['seeds'][s]['validation_signal'])}")
L+=['', '## Frozen/generated hierarchy interventions on corrupted audio','', '| Model / intervention | Raw digit % | Raw sequence top-1 % | Top-5 % | Correct-digit probability | Δ probability | Protected top-1 % | Top-5 % | ECE % | NLL |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for n in models:
 for mode in modes:
  row=[pct(val(n,'corrupted',mode,'raw',k)) for k in ['digit_accuracy','sequence_top1','sequence_top5']]+[avg(val(n,'corrupted',mode,'raw',k)) for k in ['correct_digit_probability','correct_probability_delta']]+[pct(val(n,'corrupted',mode,'protected',k)) for k in ['sequence_top1','sequence_top5','digit_ece_10_bins']]+[avg(val(n,'corrupted',mode,'protected','digit_nll'))]
  L.append('| '+n+' / '+mode+' | '+' | '.join(row)+' |')
L+=['','## Direct decoder versus downstream sensitivity','', '| Model / fixed replacement or perturbation | Raw digit % | Δ correct probability | Repairs | Regressions |','|---|---:|---:|---:|---:|']
for n in models:
 for mode in ['fixed0','fixed1','fixed2','perturb0','perturb1','perturb2']:
  L.append('| '+n+' / '+mode+' | '+' | '.join([pct(val(n,'corrupted',mode,'raw','digit_accuracy')),avg(val(n,'corrupted',mode,'raw','correct_probability_delta')),avg(val(n,'corrupted',mode,'raw','wrong_to_correct')),avg(val(n,'corrupted',mode,'raw','correct_to_wrong'))])+' |')
L+=['', '## Target-free comparison across conditions','', '| Condition / model | Codes L1 / L2 / L3 % | Raw digit % | Protected digit % | Sequence top-1 % | Top-5 % | ECE % | NLL | Brier | CPU p50 / p95 ms |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for c in cases:
 for n in models:
  codes=' / '.join(pct([r['seeds'][s]['models'][n]['cases'][c]['generated']['raw']['code_accuracy'][l] for s in seeds]) for l in range(3))
  latency=' / '.join(avg([r['seeds'][s]['models'][n]['cases'][c]['generated']['latency_ms'][k] for s in seeds]) for k in ['p50','p95'])
  L.append('| '+c+' / '+n+' | '+' | '.join([codes,pct(val(n,c,'generated','raw','digit_accuracy'))]+[pct(val(n,c,'generated','protected',k)) for k in ['digit_accuracy','sequence_top1','sequence_top5','digit_ece_10_bins']]+[avg(val(n,c,'generated','protected',k)) for k in ['digit_nll','digit_brier']]+[latency])+' |')
L+=['', 'Latency includes CNN, live gate, accepted-position NCM and candidate ranking, one CPU thread and one pass per recording. No oracle extraction or ground-truth labels enter the timed path. Noisy timing is not a rigorous speed comparison; reported p50/p95 are per-seed percentiles averaged across seeds.','', '## Score fusion control','', '| Model | Validation-selected alpha (seed order) | Corrupted top-1 % | Top-5 % | NLL |','|---|---|---:|---:|---:|']
for n in models:
 a=[r['seeds'][s]['models'][n]['selected_alpha'] for s in seeds]
 L.append('| '+n+' | '+str(a)+' | '+' | '.join([pct([r['seeds'][s]['models'][n]['cases']['corrupted']['validation_selected_fusion'][k] for s in seeds]) for k in ['sequence_top1','sequence_top5']]+[avg([r['seeds'][s]['models'][n]['cases']['corrupted']['validation_selected_fusion']['digit_nll'] for s in seeds])])+' |')
L+=['', '## Paired uncertainty','', '10,000 label-cluster bootstrap resamples over 266 unique corrupted-test sequence labels, averaging seed effects. Intervals condition on these trained seeds and do not include full training-population uncertainty.','']
summary={}
if 'recognition' in models:
 for base in ['original_joint','original_aligned']:
  for metric in ['top1','top5']:
   pairs=[];labels=None
   for s in seeds:
    a=json.loads((R/f'seed_{s}/recognition/corrupted_generated_trace.json').read_text());b=json.loads((R/f'seed_{s}/{base}/corrupted_generated_trace.json').read_text());labels=[tuple(q['label']) for q in a];pairs.append([float(x[metric])-float(y[metric]) for x,y in zip(a,b)])
   effect=np.mean(pairs,0);groups=[np.flatnonzero([x==u for x in labels]) for u in sorted(set(labels))];rng=np.random.default_rng(17)
   draws=[effect[np.concatenate([groups[i] for i in rng.integers(len(groups),size=len(groups))])].mean() for _ in range(10000)];lo,hi=np.percentile(draws,[2.5,97.5])*100
   summary[base+'_'+metric]=[float(effect.mean()*100),float(lo),float(hi)];L.append(f'- Recognition minus {base}, protected {metric}: {effect.mean()*100:+.2f} pp, 95% interval [{lo:+.2f}, {hi:+.2f}].')
L+=['', '## Reproduction and verification','', '```bash','PYTHONPATH=. .venv/bin/python experiments/decoder_sensitivity.py','PYTHONPATH=. .venv/bin/python experiments/decoder_detail.py','PYTHONPATH=. .venv/bin/python experiments/report_decoder.py','PYTHONPATH=. .venv/bin/python experiments/verify_decoder_results.py','PYTHONPATH=. .venv/bin/python -m pytest -q','```','', '46 tests passed. New checks verify unchanged generated inference, isolation of injected levels, fixed-suffix behavior, generated-path gradients and frozen codebooks. metrics.json contains all five-condition interventions, calibration, per-position digit scores, repairs/regressions, latent errors and fusion controls. detail.json contains corrupted-test correct-logit/rank/margin changes, code-vector quantization errors and coarse-correct/incorrect strata. These strata are observational, not causal effects. All oracle interventions are marked separately. Existing checkpoints are never overwritten.']
# Findings are reported separately from the exhaustive diagnostic tables.
findings=['## Findings', '', 'The frozen decoder is sensitive to code identity, especially level 1. In the original-joint model, injecting canonical L1 lowers raw digit accuracy from 88.95% to 83.49%; fixing the original suffix makes it fall further to 77.01%. Regenerating later levels partly compensates for the canonical coarse code. All canonical codes yield only 72.44%, versus 88.95% generated. This supports a learned code/decoder compatibility mismatch; canonical acoustic code fidelity is not the same objective as digit recognition.', '', 'The code-aligned model behaves differently: canonical L3 raises raw digit accuracy from 83.36% to 84.32%, and all canonical codes raise it to 86.14%. Its protected sequence top-1 rises from 66.91% to 68.64% with all oracle levels, still below the ordinary original-joint result (69.38%). Canonical fine-code errors therefore matter, but correcting them alone does not establish an NCM recognition advantage.', '', 'One recognition-aware variant was trained after each seed met the validation diagnostic threshold. Protected corrupted-test sequence top-1 is 69.14%, compared with original-joint 69.38% and code-aligned 66.91%. The difference from original-joint is −0.25 pp (95% paired interval −1.62 to +1.22); the difference from code-aligned is +2.22 pp (+0.49 to +4.18). Recognition-aware supervision recovers the code-aligned regression but does not improve on the original NCM. Its all-canonical raw accuracy falls to 55.86%, showing that the added ranking loss does not resolve canonical-code compatibility.', '', 'Validation selects full NCM weight in every seed for original-joint and recognition-aware. Code-aligned selects [1,.75,1], giving protected top-1 67.04% versus 66.91% at full weight. Thus this small fusion grid does not identify score overweighting as the main bottleneck. It cannot rule out better fusion strategies.', '', 'No NCM-specific recognition improvement is established. These are three-seed development results on reused held-out combinations; code substitutions are diagnostic interventions, and individual code correctness does not causally guarantee a better rank.', '']
L[4:4]=findings
if (R/'detail.json').exists():
 d=json.loads((R/'detail.json').read_text());extra=['', '## Prefix contribution and quantization detail', '', '| Model | Generated prefix L1 / L1+L2 / all digit accuracy % | Canonical prefix acoustic MSE |', '|---|---:|---:|']
 for n in models:
  accuracy=' / '.join(pct([d[s][n]['generated_prefix_digit_accuracy'][l] for s in seeds]) for l in range(3))
  error=' / '.join(avg([d[s][n]['canonical_prefix_quantization_mse'][l] for s in seeds]) for l in range(3))
  extra.append('| '+n+' | '+accuracy+' | '+error+' |')
 extra += ['', 'These prefix accuracies show how the shared decoder uses progressively accumulated generated representations. They do not isolate a causal benefit over a matched flat model. Decreasing acoustic quantization error alone does not guarantee improved digit ranking.', '', '| Model / intervention | Correct mean rank | Rank change (negative improves) | Correct-logit change | Code-vector MSE L1 / L2 / L3 |', '|---|---:|---:|---:|---:|']
 for n in models:
  for mode in modes:
   v=[d[s][n][mode] for s in seeds];errors=' / '.join(avg([a['code_vector_mse_to_canonical'][l] for a in v]) for l in range(3))
   extra.append('| '+n+' / '+mode+' | '+' | '.join([avg([a[k] for a in v]) for k in ['correct_mean_rank','correct_rank_delta','correct_logit_delta']]+[errors])+' |')
 L[L.index('## Reproduction and verification'):L.index('## Reproduction and verification')]=extra+['']
(R/'REPORT.md').write_text('\n'.join(L)+'\n');(R/'summary.json').write_text(json.dumps(summary,indent=2));print(R/'REPORT.md')
